"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { FormEvent, ReactNode, useCallback, useEffect, useState } from "react";
import { api, ApiError, Approval, AuditEvent, Automation, Organization, Row, Session, Skill, Spending } from "@/lib/api";
import Icon, { Brand } from "./icon";
import { AnomalyPanel, AssistedSetup, BusinessLaunch, ChannelOperations, ChannelRecords, ConnectionNotice, DataRights, NativeAssistant, ProviderConnect, ShopifyClaim, TrialEvidence } from "./operations";

const nav = [
  ["/", "Business Pulse", "pulse"], ["/automations", "Automations", "layers"], ["/explore", "Explore skills", "grid"],
  ["/approvals", "Approval inbox", "shield"], ["/activity", "Activity", "clock"], ["/connections", "Connections", "link"],
  ["/knowledge", "Business knowledge", "box"], ["/costs", "Costs & insights", "chart"], ["/security", "Team & security", "team"],
  ["/business-launch", "Business launch", "box"], ["/channels", "Business channels", "link"], ["/assistant", "Gluons assistant", "spark"], ["/assisted-setup", "Assisted setup", "team"], ["/data", "Your data", "shield"],
] as const;
const human = (text: unknown) => String(text ?? "—").replaceAll("_", " ").replaceAll(".", " · ");
const date = (text: unknown) => text ? new Date(String(text)).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" }) : "—";
const money = (value: unknown) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 4 }).format(Number(value || 0));
const json = (value: unknown) => JSON.stringify(value, null, 2);

function Badge({ children, status = "" }: { children: ReactNode; status?: string }) { return <span className={`badge ${["active", "verified", "connected", "completed", "live_verified"].includes(status) ? "green" : ["failed", "cancelled", "denied"].includes(status) ? "red" : ["pending", "waiting_approval", "shadow", "trial_shadow"].includes(status) ? "amber" : "neutral"}`}><span />{children}</span>; }
function ErrorBox({ error, retry }: { error: string | null; retry?: () => void }) { if (!error) return null; return <div className="error-box" role="alert"><Icon name="alert" /><span>{error}</span>{retry && <button className="text-button" onClick={retry}>Try again</button>}</div>; }
function Empty({ icon = "layers", title, children, action }: { icon?: string; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty-state"><span className="empty-icon"><Icon name={icon} size={26} /></span><h3>{title}</h3><p>{children}</p>{action}</div>; }
function Panel({ title, meta, children, className = "" }: { title?: string; meta?: ReactNode; children: ReactNode; className?: string }) { return <section className={`panel ${className}`}>{title && <div className="panel-heading"><h2>{title}</h2>{meta}</div>}{children}</section>; }
function Loading() { return <div className="loading" role="status"><span className="spinner" />Loading your workspace…</div>; }
function useResource<T>(path: string) {
  const [data, setData] = useState<T | null>(null); const [error, setError] = useState<string | null>(null); const [loading, setLoading] = useState(true);
  const load = useCallback(async () => { setLoading(true); setError(null); try { setData(await api<T>(path)); } catch (e) { setError((e as Error).message); } finally { setLoading(false); } }, [path]);
  useEffect(() => { void load(); }, [load]);
  return { data, error, loading, load };
}
function PageTitle({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description: string; action?: ReactNode }) { return <div className="page-title"><div><div className="eyebrow">{eyebrow || "YOUR WORKSPACE"}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>; }
function JsonView({ value }: { value: unknown }) { return <pre className="json-view">{json(value)}</pre>; }

export default function Console() {
  const pathname = usePathname(); const router = useRouter();
  const [session, setSession] = useState<Session | null>(null); const [org, setOrg] = useState<Organization | null>(null);
  const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null); const [mobile, setMobile] = useState(false);
  const [notifications, setNotifications] = useState<Row[] | null>(null);
  const loadSession = useCallback(async () => {
    setError(null);
    try { const value = await api<Session>("/v1/auth/session"); setSession(value); if (value.active_organization_id && !value.mfa_pending) setOrg(await api<Organization>("/v1/organizations/current")); else setOrg(null); }
    catch (e) { setSession(null); setOrg(null); if (!(e instanceof ApiError && e.status === 401)) setError((e as Error).message); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { void loadSession(); }, [loadSession]);
  useEffect(() => { setMobile(false); }, [pathname]);
  const authPage = ["/login", "/register", "/verify-email", "/reset-password", "/forgot-password"].includes(pathname);
  if (loading) return <main className="startup"><Brand /><Loading /></main>;
  if (!session || authPage || session.mfa_pending) return <Auth path={session?.mfa_pending ? "/mfa" : pathname} initialError={error} onSignedIn={async () => { await loadSession(); if (authPage || pathname === "/mfa") router.push("/"); }} />;
  if (!session.active_organization_id || pathname === "/org/select") return <OrganizationSelect session={session} onDone={async () => { await loadSession(); if (pathname === "/org/select") router.push("/"); }} />;
  const active = nav.find(([path]) => path === "/" ? pathname === "/" : pathname.startsWith(path));
  const can = (permission: string) => org?.permissions?.includes(permission) || false;
  return <div className="app-shell"><a href="#main-content" className="skip-link">Skip to main content</a>
    {mobile && <button className="sidebar-overlay" aria-label="Close navigation" onClick={() => setMobile(false)} />}
    <aside className={`sidebar ${mobile ? "is-open" : ""}`}><Link href="/" aria-label="Gluons home"><Brand /></Link>
      <button className="workspace-selector" onClick={() => router.push("/org/select")}><span className="workspace-avatar">{org?.name?.[0] || "G"}</span><span><strong>{org?.name || "My business"}</strong><small>{human(org?.role)} workspace</small></span><Icon name="down" size={16} /></button>
      <div className="nav-label">WORKSPACE</div><nav aria-label="Main navigation">{nav.map(([path, label, icon]) => <Link key={path} href={path} aria-label={label} className={`nav-item ${active?.[0] === path ? "active" : ""}`} aria-current={active?.[0] === path ? "page" : undefined}><Icon name={icon} /><span>{label}</span>{path === "/explore" && <small className="nav-new">DISCOVER</small>}</Link>)}</nav>
      <div className="sidebar-bottom"><div className="trust-card"><Icon name="shield" size={20} /><strong>Your business. Your rules.</strong><p>Every action follows your permissions and spending limits.</p><Link href="/security">Review your controls <Icon name="arrow" size={14} /></Link></div><div className="sidebar-user"><span className="user-avatar">{session.user.display_name?.[0]}</span><span><strong>{session.user.display_name}</strong><small>{session.user.email}</small></span><button className="icon-button" aria-label="Sign out" onClick={async () => { await api("/v1/auth/logout", { method: "POST" }); setSession(null); router.push("/login"); }}><Icon name="logout" size={17} /></button></div></div>
    </aside>
    <div className="workspace"><header className="topbar"><div className="breadcrumbs"><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={() => setMobile(true)}><Icon name="menu" /></button><span>{org?.name}</span><span className="slash">/</span><strong>{active?.[1] || "Workspace"}</strong></div><div className="top-actions"><Badge status="connected">{human(session.environment)} environment</Badge><span className="top-divider" /><button className="icon-button" aria-label="Notifications" onClick={async () => { if (notifications) setNotifications(null); else { try { const r = await api<{ notifications: Row[] }>("/v1/notifications"); setNotifications(r.notifications); } catch (e) { setError((e as Error).message); } } }}><Icon name="bell" /></button><span className="user-avatar small">{session.user.display_name?.[0]}</span></div></header>
      {notifications && <div className="notification-popover"><h3>Notifications</h3>{notifications.length ? notifications.map(n => <div className="notification" key={String(n.id)}><strong>{String(n.title)}</strong><p>{String(n.body)}</p>{!n.read && <button className="text-button" onClick={async () => { await api(`/v1/notifications/${n.id}/read`, { method: "POST" }); setNotifications(notifications.map(item => item.id === n.id ? { ...item, read: true } : item)); }}>Mark read</button>}</div>) : <p>You’re all caught up.</p>}</div>}
      <main id="main-content"><ErrorBox error={error} />{org?.emergency_stop_at && <div className="emergency-banner"><Icon name="stop" /><span><strong>Emergency stop is on.</strong> New external actions are blocked for this business.</span>{can("emergency:stop") && <button onClick={async () => { await api("/v1/organizations/current/emergency-stop", { method: "POST", body: { active: false } }); await loadSession(); }}>Release stop</button>}</div>}
        {pathname.startsWith("/connect/shopify/") ? <ShopifyClaim id={pathname.split("/")[3]} organization={String(org?.name ?? "")} /> : pathname === "/business-launch" ? <BusinessLaunch can={can} /> : pathname === "/channels" ? <><ChannelOperations can={can} /><ChannelRecords /></> : pathname === "/data" ? <DataRights can={can} organization={String(org?.name ?? "")} /> : pathname === "/assistant" ? <NativeAssistant /> : pathname === "/assisted-setup" ? <AssistedSetup can={can} /> : pathname === "/" ? <Home session={session} org={org} /> : pathname === "/explore" ? <Explore /> : pathname.startsWith("/explore/") ? <SkillDetail id={pathname.split("/")[2]} /> : pathname === "/automations" ? <Automations /> : (pathname.startsWith("/automations/") || pathname.startsWith("/tasks/")) ? <TaskDetail id={pathname.split("/")[2]} can={can} /> : pathname.startsWith("/runs/") ? <RunDetail id={pathname.split("/")[2]} /> : pathname === "/approvals" ? <Approvals can={can} /> : pathname === "/activity" || pathname === "/audit" ? <Activity /> : pathname === "/connections" || pathname.startsWith("/setup/") ? <Connections path={pathname} can={can} /> : pathname === "/knowledge" ? <Knowledge can={can} /> : pathname === "/costs" ? <><Costs org={org} can={can} onUpdate={loadSession} /><AnomalyPanel /></> : pathname === "/security" || pathname.startsWith("/security/") ? <Security session={session} org={org} can={can} onUpdate={loadSession} /> : pathname === "/assistant-consent" ? <AssistantConsent /> : pathname === "/invite" ? <AcceptInvite onDone={loadSession} /> : <Empty title="This page is unavailable" action={<Link className="button primary" href="/">Back to Business Pulse</Link>}>Choose a page from your workspace navigation.</Empty>}
      </main><footer className="app-footer"><span><span className="status-dot" /> Connected to your Gluons workspace</span><span>Automation with accountability.</span></footer>
    </div>
  </div>;
}

function Auth({ path, initialError, onSignedIn }: { path: string; initialError: string | null; onSignedIn: () => Promise<void> }) {
  const router = useRouter(); const [error, setError] = useState(initialError); const [busy, setBusy] = useState(false); const [notice, setNotice] = useState(""); const [token, setToken] = useState("");
  const register = path === "/register", verify = path === "/verify-email", reset = path === "/reset-password", forgot = path === "/forgot-password", mfa = path === "/mfa";
  useEffect(() => { setToken(new URLSearchParams(window.location.search).get("token") || ""); setNotice(""); setError(initialError); }, [path, initialError]);
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(null); const fields = Object.fromEntries(new FormData(event.currentTarget));
    try {
      if (register) { await api("/v1/auth/register", { method: "POST", body: fields }); setNotice("Check your email for a verification link. Local development delivers messages to .gluons-data/mail on the API server."); }
      else if (verify) { await api("/v1/auth/verify-email", { method: "POST", body: { token } }); setNotice("Your email is verified. You can now sign in."); }
      else if (forgot) { await api("/v1/auth/password-reset/request", { method: "POST", body: fields }); setNotice("If your email is registered, you’ll receive a password reset message."); }
      else if (reset) { await api("/v1/auth/password-reset/confirm", { method: "POST", body: { token, new_password: fields.password } }); setNotice("Password updated. Sign in with your new password."); }
      else if (mfa) { await api("/v1/auth/mfa/verify", { method: "POST", body: fields }); await onSignedIn(); }
      else { const result = await api<{ status: string }>("/v1/auth/login", { method: "POST", body: fields }); if (result.status === "mfa_required") { router.push("/mfa"); await onSignedIn(); } else await onSignedIn(); }
    } catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  }
  return <main className="auth-shell"><section className="auth-story"><Brand /><div><div className="eyebrow">BUSINESS AUTOMATION, WITH YOU IN CONTROL</div><h1>Less busywork.<br />More possibility.</h1><p>Put your everyday operations in motion.<br />Keep every decision that matters in your hands.</p><div className="orbit-art" aria-hidden="true"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><span className="orbit-center"><Icon name="spark" size={42} /></span><span className="orbit-node node-one"><Icon name="mail" size={24} /></span><span className="orbit-node node-two"><Icon name="box" size={24} /></span><span className="orbit-node node-three"><Icon name="shield" size={24} /></span><span className="orbit-node node-four"><Icon name="chart" size={24} /></span></div></div><span className="auth-footnote"><Icon name="shield" size={16} /> Independent assistants. One trusted workspace.</span></section><section className="auth-form-wrap"><div className="auth-mobile-brand"><Brand /></div><div className="auth-form"><div className="eyebrow">WELCOME TO GLUONS</div><h2>{register ? "Build a little more freedom." : verify ? "Verify your email." : reset ? "Choose a new password." : forgot ? "Let’s get you back in." : mfa ? "One more check." : "Welcome back."}</h2><p>{register ? "Create your account to start shaping better operations." : verify ? "Confirm your address before connecting a business." : reset || forgot ? "Recover access to your Gluons workspace." : mfa ? "Enter your authenticator code or a recovery code." : "Sign in to your business control room."}</p><ErrorBox error={error} />{notice && <div className="success-box" role="status"><Icon name="check" />{notice}</div>}
      <form onSubmit={submit}>{register && <label>Your name<input name="display_name" required maxLength={200} autoComplete="name" placeholder="Alex Morgan" /></label>}{!verify && !reset && !mfa && <label>Email address<input name="email" type="email" required autoComplete="email" placeholder="you@yourbusiness.com" /></label>}{!verify && !forgot && !mfa && <label>Password<input name="password" type="password" required minLength={register || reset ? 12 : undefined} maxLength={200} autoComplete={register || reset ? "new-password" : "current-password"} placeholder={register || reset ? "At least 12 characters" : "Enter your password"} /></label>}{verify && <label>Verification token<input value={token} onChange={e => setToken(e.target.value)} required autoComplete="off" placeholder="Open the link in your verification email" /></label>}{reset && <label>Reset token<input value={token} onChange={e => setToken(e.target.value)} required autoComplete="off" /></label>}{mfa && <label>Verification code<input name="code" required autoComplete="one-time-code" placeholder="6-digit code or recovery code" /></label>}{!register && !verify && !reset && !forgot && !mfa && <Link href="/forgot-password" className="forgot-link">Forgot password?</Link>}<button className="button primary wide" disabled={busy}>{busy ? "Please wait…" : register ? "Create your account" : verify ? "Verify email" : reset ? "Update password" : forgot ? "Send recovery link" : mfa ? "Verify and continue" : "Sign in"}<Icon name="arrow" size={17} /></button></form>
      <p className="auth-switch">{register ? "Already have an account? " : "New to Gluons? "}<Link href={register ? "/login" : "/register"}>{register ? "Sign in" : "Create an account"}</Link></p>{(verify || reset || forgot) && <Link className="text-button" href="/login">Back to sign in</Link>}<div className="auth-disclosure"><Icon name="shield" size={16} /><span>Your provider accounts stay yours. Connecting a service never grants permission to act.</span></div></div></section></main>;
}

function OrganizationSelect({ session, onDone }: { session: Session; onDone: () => Promise<void> }) {
  const [error, setError] = useState<string | null>(null); const [busy, setBusy] = useState(false);
  return <main className="onboarding-page"><Brand /><div className="onboarding-card"><div className="eyebrow">YOUR BUSINESS, YOUR WORKSPACE</div><h1>{session.organizations.length ? "Choose your business." : "Make room for better work."}</h1><p>Each business has its own connections, people, permissions and budget.</p><ErrorBox error={error} />{session.organizations.map(o => <button className="org-choice" key={o.id} onClick={async () => { try { await api(`/v1/organizations/${o.id}/select`, { method: "POST" }); await onDone(); } catch (e) { setError((e as Error).message); } }}><span className="workspace-avatar">{o.name[0]}</span><span><strong>{o.name}</strong><small>{human(o.role)}</small></span><Icon name="arrow" /></button>)}{session.organizations.length > 0 && <div className="form-divider">or add a business</div>}<form onSubmit={async e => { e.preventDefault(); setBusy(true); setError(null); const fields = Object.fromEntries(new FormData(e.currentTarget)); try { await api("/v1/organizations", { method: "POST", body: { name: fields.name, industry: fields.industry || null, country: fields.country || null } }); await onDone(); } catch (err) { setError((err as Error).message); } finally { setBusy(false); } }}><label>Business name<input name="name" required placeholder="Your business name" maxLength={200} /></label><div className="form-grid"><label>Industry<input name="industry" placeholder="e.g. Food distribution" /></label><label>Country code<input name="country" minLength={2} maxLength={2} placeholder="IN" pattern="[A-Za-z]{2}" /></label></div><button className="button primary wide" disabled={busy}>Create business workspace<Icon name="arrow" size={17} /></button></form></div></main>;
}

function Home({ session, org }: { session: Session; org: Organization | null }) {
  const tasks = useResource<{ automations: Automation[] }>("/v1/automations"); const approvals = useResource<{ approvals: Approval[] }>("/v1/approvals"); const spending = useResource<Spending>("/v1/billing/usage"); const activity = useResource<{ events: AuditEvent[] }>("/v1/audit/events?limit=5");
  const rows = tasks.data?.automations || []; const running = rows.filter(a => a.status === "active").length; const trials = rows.filter(a => a.status.startsWith("trial_")).length;
  return <><PageTitle eyebrow="BUSINESS PULSE" title={`A clearer view. A calmer day.`} description={`Welcome back, ${session.user.display_name.split(" ")[0]}. Here’s what’s happening at ${org?.name}.`} action={<Link className="button primary" href="/explore"><Icon name="plus" size={17} /> New automation</Link>} /><ErrorBox error={tasks.error} retry={tasks.load} />
    <div className="stat-grid"><Stat label="Active automations" value={tasks.loading ? "—" : String(running)} icon="layers" note={`${rows.length} total in your workspace`} /><Stat label="Needs your approval" value={approvals.loading || approvals.error ? "—" : String(approvals.data?.approvals.length || 0)} icon="shield" note="Your decisions keep work moving" accent /><Stat label="Trial automations" value={tasks.loading ? "—" : String(trials)} icon="spark" note="Learning before taking action" /><Stat label="Usage this month" value={spending.data ? money(spending.data.total_usd) : "—"} icon="money" note={spending.data?.monthly_budget_usd ? `${money(spending.data.monthly_budget_usd)} monthly budget` : "Recorded usage, before provider reconciliation"} /></div>
    {!rows.length && !tasks.loading ? <section className="welcome-hero"><div><span className="hero-tag"><Icon name="spark" size={14} /> A LITTLE LESS ON YOUR PLATE</span><h2>Give the routine<br />a better rhythm.</h2><p>From incoming orders to everyday follow-ups, find an automation that fits your business. Start in shadow mode and see the work before it acts.</p><Link className="button primary" href="/explore">Find your first automation<Icon name="arrow" size={17} /></Link><span className="hero-note"><Icon name="shield" size={14} /> You choose what runs. You stay in control.</span></div><div className="workflow-art" aria-hidden="true"><div className="art-dot-grid" /><div className="art-card card-in"><span className="art-icon"><Icon name="mail" /></span><span><strong>Incoming request</strong><small>Email · message · call</small></span></div><div className="art-connector" /><div className="art-card card-core"><span className="art-icon"><Icon name="spark" /></span><span><strong>Gluons workflow</strong><small>Your rules, applied</small></span><Icon name="check" size={16} /></div><div className="art-connector short" /><div className="art-card card-out"><span className="art-icon"><Icon name="shield" /></span><span><strong>Ready for your review</strong><small>Evidence at every step</small></span></div><span className="art-pill"><span className="status-dot" /> Built around your business</span></div></section> : <Panel title="Your automations" meta={<Link href="/automations" className="text-button">View all<Icon name="arrow" size={15} /></Link>}>{tasks.loading ? <Loading /> : <AutomationList rows={rows.slice(0, 5)} />}</Panel>}
    <div className="home-bottom"><Panel title="Your next steps" meta={<span className="subtle">Make it yours</span>}><div className="setup-list"><SetupStep number="01" title="Your business, connected" text="Authorize your tools through their secure provider sign-in." href="/connections" icon="link" /><SetupStep number="02" title="Find the right workflow" text="Explore the catalog and inspect each skill’s prerequisites." href="/explore" icon="grid" /><SetupStep number="03" title="See the proof first" text="Run a shadow trial before approving any external action." href="/automations" icon="shield" /></div></Panel><Panel title="Recent activity" meta={<Link className="text-button" href="/activity">View history<Icon name="arrow" size={15} /></Link>}>{activity.data?.events.length ? <div className="activity-list">{activity.data.events.map(e => <div className="activity-item" key={e.seq}><span className="activity-symbol"><Icon name={e.category === "permission" ? "shield" : "layers"} size={16} /></span><div><strong>{human(e.event_type)}</strong><small>{date(e.created_at)}</small></div></div>)}</div> : <Empty icon="clock" title="Your story starts here">Workspace events and decisions will appear here as you work.</Empty>}</Panel></div>
  </>;
}
function Stat({ label, value, icon, note, accent }: { label: string; value: string; icon: string; note: string; accent?: boolean }) { return <div className={`stat ${accent ? "stat-accent" : ""}`}><div className="stat-top"><span>{label}</span><Icon name={icon} size={18} /></div><strong>{value}</strong><small>{note}</small></div>; }
function SetupStep({ number, title, text, href, icon }: { number: string; title: string; text: string; href: string; icon: string }) { return <Link className="setup-step" href={href}><span className="step-number">{number}</span><div><strong>{title}</strong><p>{text}</p></div><Icon name={icon} size={18} /></Link>; }

function Automations() {
  const { data, error, loading, load } = useResource<{ automations: Automation[] }>("/v1/automations"); const [filter, setFilter] = useState("all"); const rows = (data?.automations || []).filter(a => filter === "all" || a.status === filter || (filter === "trial" && a.status.startsWith("trial_")));
  return <><PageTitle title="Work that keeps moving." description="Persistent workflows, clear controls and a record of every action." action={<Link href="/explore" className="button primary"><Icon name="plus" size={17} />New automation</Link>} /><div className="tabs" role="group" aria-label="Filter automations">{["all", "active", "trial", "paused", "cancelled"].map(s => <button className={filter === s ? "selected" : ""} key={s} onClick={() => setFilter(s)}>{s === "all" ? "All automations" : human(s)}</button>)}</div><ErrorBox error={error} retry={load} /><Panel>{loading ? <Loading /> : rows.length ? <AutomationList rows={rows} /> : <Empty title="No automations here yet" action={<Link href="/explore" className="button primary">Explore skills<Icon name="arrow" size={16} /></Link>}>Find the right skill, review what it needs and start a bounded trial.</Empty>}</Panel></>;
}
function AutomationList({ rows }: { rows: Automation[] }) { return <div className="automation-list">{rows.map(a => <Link className="automation-row" href={`/automations/${a.id}`} key={a.id}><span className="row-icon"><Icon name="layers" /></span><div className="automation-name"><strong>{a.name}</strong><small>{human(a.skill_id)}</small></div><Badge status={a.status}>{human(a.status)}</Badge><span className="mode-label">{human(a.mode)}</span><Icon name="chevron" size={16} /></Link>)}</div>; }

function Explore() {
  const { data, error, loading, load } = useResource<{ skills: Skill[] }>("/v1/skills"); const [query, setQuery] = useState(""); const [industry, setIndustry] = useState("all");
  const rows = (data?.skills || []).filter(s => (industry === "all" || s.industry === industry) && `${s.title} ${s.industry} ${s.outcome}`.toLowerCase().includes(query.toLowerCase()));
  return <><PageTitle eyebrow="EXPERT WORKFLOWS. SHARED CONTROLS." title="Find your next possibility." description="Purpose-built skills for everyday operations. Inspect the capabilities, connections and limits before you start." /><div className="explore-toolbar"><div className="search-input"><Icon name="search" size={19} /><input aria-label="Search skills" placeholder="Search a problem, workflow or industry…" value={query} onChange={e => setQuery(e.target.value)} /></div><select aria-label="Filter industry" value={industry} onChange={e => setIndustry(e.target.value)}><option value="all">All industries</option>{Array.from(new Set(data?.skills.map(s => s.industry))).map(i => <option key={i}>{i}</option>)}</select><span className="subtle">{rows.length} skills</span></div><ErrorBox error={error} retry={load} />{loading ? <Loading /> : <div className="skill-grid">{rows.map((s, i) => <Link href={`/explore/${s.id}`} className="skill-card" key={s.id}><div className="skill-card-top"><span className={`skill-icon tone-${i % 4}`}><Icon name={s.id.includes("order") ? "box" : s.id.includes("voice") ? "pulse" : s.id.includes("account") ? "money" : "layers"} size={23} /></span><span className="risk-label">{s.risk_tier}</span></div><span className="skill-industry">{s.industry}</span><h2>{s.title}</h2><p>{s.outcome || `Expert workflow for ${s.industry.toLowerCase()} operations.`}</p><div className="skill-card-bottom"><Badge>{human(s.capability.status)}</Badge><Icon name="arrow" size={17} /></div></Link>)}</div>}{!loading && !rows.length && <Empty icon="search" title="No matching skills">Try a broader problem or choose another industry.</Empty>}</>;
}

function SkillDetail({ id }: { id: string }) {
  const router = useRouter(); const { data: skill, error, loading, load } = useResource<Skill>(`/v1/skills/${id}`); const [busy, setBusy] = useState(false); const [failure, setFailure] = useState<string | null>(null);
  if (loading) return <Loading />; if (!skill) return <ErrorBox error={error} retry={load} />;
  return <><Link className="back-link" href="/explore">← All skills</Link><PageTitle eyebrow={skill.industry} title={skill.title} description={skill.outcome || "Review the workflow and its requirements."} /><div className="detail-grid"><div><Panel title="What this skill can do"><div className="panel-body"><Badge>{human(skill.capability.status)}</Badge><p className="body-copy">Live readiness depends on verified connections, successful evaluations and your signed action policy.</p><div className="capability-list">{skill.actions?.map(a => <div key={String(a.name)}><Icon name={a.is_write ? "shield" : "check"} size={18} /><span><strong>{human(a.name)}</strong><small>{String(a.description || "Action permissions are checked by the server.")}</small></span><Badge>{a.is_write ? "External action" : "Read only"}</Badge></div>)}</div>{skill.limitations?.length ? <><h3>Known limits</h3><ul className="plain-list">{skill.limitations.map((l, i) => <li key={i}>{l}</li>)}</ul></> : null}</div></Panel><Panel title="Connections and prerequisites"><div className="panel-body">{skill.connectors.map(c => <div className="requirement" key={c.capability}><span className="row-icon"><Icon name="link" /></span><div><strong>{human(c.capability)}</strong><p>{c.purpose}</p><small>{c.providers.join(" · ")}</small></div><Badge>{c.required_for_live ? "Required for live" : "Optional"}</Badge></div>)}{skill.capability.blockers.map((b, i) => <div className="notice-box" key={i}><Icon name="alert" size={17} /><span>{String(b.description || b.requirement || b.name || Object.values(b).join(" · "))}</span></div>)}</div></Panel></div><Panel title="Start with a draft" className="setup-panel"><div className="panel-body"><p className="body-copy">Create a persistent automation. Nothing runs and no provider action is authorized until you start a trial or activate it.</p><ErrorBox error={failure} /><form onSubmit={async e => { e.preventDefault(); setBusy(true); setFailure(null); const fields = Object.fromEntries(new FormData(e.currentTarget)); try { const result = await api<Automation>("/v1/automations", { method: "POST", idempotent: true, body: { skill_id: id, name: fields.name, monthly_budget_usd: fields.budget ? Number(fields.budget) : null, config: {} } }); router.push(`/automations/${result.id}`); } catch (err) { setFailure((err as Error).message); } finally { setBusy(false); } }}><label>Automation name<input name="name" defaultValue={skill.title} maxLength={200} required /></label><label>Monthly budget (USD)<input name="budget" type="number" min="0" step="0.01" placeholder="Optional spending ceiling" /></label><button className="button primary wide" disabled={busy}>{busy ? "Creating…" : "Create draft automation"}<Icon name="arrow" size={17} /></button></form><p className="small-print"><Icon name="shield" size={14} /> Shadow and replay trials perform no external writes.</p></div></Panel></div></>;
}

function TaskDetail({ id, can }: { id: string; can: (p: string) => boolean }) {
  const task = useResource<Automation>(`/v1/automations/${id}`); const runs = useResource<{ runs: Row[] }>(`/v1/automations/${id}/runs`); const evidence = useResource<{ receipts: Row[]; verified_count: number; previews: number }>(`/v1/automations/${id}/evidence`);
  const [error, setError] = useState<string | null>(null); const [notice, setNotice] = useState(""); const [busy, setBusy] = useState(false); const [tab, setTab] = useState("overview");
  const a = task.data;
  useEffect(() => { if (!a || ["cancelled", "completed", "failed_terminal"].includes(a.status)) return; const timer = window.setInterval(() => { void task.load(); void runs.load(); void evidence.load(); }, 3000); return () => window.clearInterval(timer); }, [a?.status, task.load, runs.load, evidence.load]);
  async function command(action: string, body: Row = {}) { if (!a) return; setBusy(true); setError(null); setNotice(""); try { await api(`/v1/automations/${id}/${action}`, { method: "POST", body: { expected_version: a.version, ...body } }); await task.load(); await runs.load(); setNotice(action === "cancel" ? "Cancellation recorded. Already committed external actions remain in the evidence history." : `${human(action)} recorded.`); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  if (task.loading && !a) return <Loading />; if (!a) return <ErrorBox error={task.error} retry={task.load} />;
  return <><Link className="back-link" href="/automations">← All automations</Link><PageTitle title={a.name} description={`${human(a.skill_id)} · Version ${a.version}`} action={<Badge status={a.status}>{human(a.status)}</Badge>} /><ErrorBox error={error || task.error} retry={task.load} />{notice && <div className="success-box" role="status"><Icon name="check" />{notice}</div>}<div className="task-controls"><Badge status={a.mode}>{human(a.mode || "draft")}</Badge><span className="subtle">State is stored independently of your assistant.</span><div className="control-buttons">{can("trials:write") && ["draft", "configuring", "ready", "awaiting_activation"].includes(a.status) && <button className="button primary" disabled={busy} onClick={() => command("start-trial", { mode: "shadow" })}><Icon name="play" size={16} />Start shadow trial</button>}{can("tasks:control") && !["paused", "cancelled", "completed"].includes(a.status) && <button className="button secondary" disabled={busy} onClick={() => command("pause")}><Icon name="pause" size={16} />Pause</button>}{can("tasks:control") && a.status === "paused" && <button className="button primary" disabled={busy} onClick={() => command("resume")}><Icon name="play" size={16} />Resume</button>}{can("tasks:control") && a.status !== "cancelled" && <button className="button danger-outline" disabled={busy} onClick={() => command("cancel")}><Icon name="stop" size={16} />Cancel automation</button>}</div></div><div className="tabs">{["overview", "runs", "trials", "evidence", "configuration", "permissions"].map(t => <button className={tab === t ? "selected" : ""} key={t} onClick={() => setTab(t)}>{human(t)}</button>)}</div>
    {tab === "overview" && <div className="detail-grid"><Panel title="Runtime overview"><div className="panel-body"><dl className="facts"><div><dt>Mode</dt><dd>{human(a.mode)}</dd></div><div><dt>Created</dt><dd>{date(a.created_at)}</dd></div><div><dt>Budget</dt><dd>{a.monthly_budget_usd ? money(a.monthly_budget_usd) : "No automation ceiling configured"}</dd></div><div><dt>Verified external receipts</dt><dd>{evidence.data?.verified_count ?? "—"}</dd></div><div><dt>Task ID</dt><dd className="mono">{a.id}</dd></div></dl><div className="notice-box"><Icon name="shield" size={18} />External writes require a verified provider connection and an owner-signed action policy. Shadow and replay produce previews only.</div></div></Panel><Panel title="Try an input"><div className="panel-body"><p className="body-copy">Submit a manual event to the running trial. The worker processes this input using the skill’s validated workflow.</p><form onSubmit={async e => { e.preventDefault(); const f = new FormData(e.currentTarget); setError(null); try { const payload = JSON.parse(String(f.get("payload"))); await api(`/v1/automations/${id}/events`, { method: "POST", body: { source: "manual", source_event_id: crypto.randomUUID(), payload } }); setNotice("Input queued. Refresh runs after the worker processes it."); await runs.load(); } catch (err) { setError(err instanceof SyntaxError ? "Enter a valid JSON object for this skill’s input." : (err as Error).message); } }}><label>Skill input<textarea name="payload" rows={7} defaultValue={'{\n  "text": "Your test input"\n}'} required spellCheck={false} /></label><button className="button secondary wide" disabled={!can("trials:write")}>Submit trial input<Icon name="arrow" size={16} /></button></form></div></Panel></div>}
    {tab === "runs" && <Panel title="Execution history" meta={<button className="text-button" onClick={runs.load}><Icon name="refresh" size={16} />Refresh</button>}><ErrorBox error={runs.error} />{runs.data?.runs.length ? <div className="table-wrap"><table><thead><tr><th>Run</th><th>Status</th><th>Source / mode</th><th>Recorded cost</th><th>Created</th></tr></thead><tbody>{runs.data.runs.map(r => <tr key={String(r.id)}><td className="mono"><Link className="text-button" href={`/runs/${r.id}`}>{String(r.id)}</Link></td><td><Badge status={String(r.status)}>{human(r.status)}</Badge></td><td>{human(r.source)} · {human(r.mode)}</td><td>{money(r.cost_usd)}</td><td>{date(r.created_at)}</td></tr>)}</tbody></table></div> : <Empty icon="clock" title="No runs recorded">Start a trial and submit an input to see the execution history.</Empty>}</Panel>}
    {tab === "evidence" && <Panel title="External action evidence"><div className="panel-body"><ErrorBox error={evidence.error} />{evidence.data?.receipts.length ? evidence.data.receipts.map(r => <div className="receipt" key={String(r.id)}><div className="inline-between"><strong>{human(r.action)}</strong><Badge status={r.verified ? "verified" : "pending"}>{r.verified ? "Verified by readback" : human(r.status)}</Badge></div><p>{String(r.provider)} · {String(r.environment)} · {human(r.mode)}</p><JsonView value={r} /></div>) : <Empty icon="shield" title="Evidence appears after execution">A provider write is verified only after an independent readback confirms the record.</Empty>}</div></Panel>}
    {tab === "configuration" && <Panel title="Workflow configuration"><div className="panel-body narrow"><ErrorBox error={error} /><form key={a.version} onSubmit={async e => { e.preventDefault(); setError(null); try { const config = JSON.parse(String(new FormData(e.currentTarget).get("config"))); await api(`/v1/automations/${id}`, { method: "PATCH", body: { config, expected_version: a.version } }); setNotice("Configuration saved."); await task.load(); } catch (err) { setError((err as Error).message); } }}><label>Skill configuration<textarea rows={16} name="config" defaultValue={json(a.config)} spellCheck={false} /></label><button className="button primary" disabled={!can("automations:write")}>Save configuration</button></form></div></Panel>}
    {tab === "trials" && <TrialStudio automation={a} can={can} onChange={task.load} />}{tab === "permissions" && <Policies automation={a} can={can} onChange={task.load} />}
  </>;
}

function Policies({ automation, can, onChange }: { automation: Automation; can: (p: string) => boolean; onChange: () => Promise<void> }) {
  const { data, error, load } = useResource<{ policies: Row[] }>(`/v1/automations/${automation.id}/policies`); const [failure, setFailure] = useState<string | null>(null); const [notice, setNotice] = useState("");
  return <div className="detail-grid"><Panel title="Action grants"><div className="panel-body"><ErrorBox error={error || failure} />{notice && <div className="success-box">{notice}</div>}{data?.policies.length ? data.policies.map(p => <div className="receipt" key={String(p.id)}><div className="inline-between"><strong>Policy {String(p.policy_version)}</strong><Badge status={String(p.status)}>{human(p.status)}</Badge></div><p>{human(p.mode)} · {String(p.currency || "USD")}</p><JsonView value={{ allowed_actions: p.allowed_actions, connection_ids: p.connection_ids, resource_filters: p.resource_filters, requires_approval_for: p.requires_approval_for, auto_limits: p.auto_limits, spend_limit_minor_per_month: p.spend_limit_minor_per_month, per_action_limit_minor: p.per_action_limit_minor, currency: p.currency, data_disclosures: p.data_disclosures, expires_at: p.expires_at }} /><div className="button-row">{can("policies:sign") && p.status === "proposed" && <button className="button primary" onClick={async () => { try { await api(`/v1/automation-policies/${p.id}/sign`, { method: "POST" }); await load(); await onChange(); } catch (e) { setFailure((e as Error).message); } }}>Sign this exact policy</button>}{can("policies:write") && p.status !== "revoked" && <button className="button danger-outline" onClick={async () => { try { await api(`/v1/automation-policies/${p.id}/revoke`, { method: "POST" }); await load(); await onChange(); } catch (e) { setFailure((e as Error).message); } }}>Revoke policy</button>}</div></div>) : <Empty icon="shield" title="No action policy signed">Connecting an account does not authorize this automation to act.</Empty>}</div></Panel><Panel title="Propose a bounded policy"><div className="panel-body"><form onSubmit={async e => { e.preventDefault(); setFailure(null); const fields = Object.fromEntries(new FormData(e.currentTarget)); try { const actions = String(fields.actions).split(",").map(s => s.trim()).filter(Boolean); const recipient = String(fields.recipient || "").trim(); if (recipient && actions.length !== 1) throw new Error("A recipient restriction requires exactly one action."); const expiry = String(fields.expires || ""); await api(`/v1/automation-policies?automation_id=${automation.id}`, { method: "POST", body: { mode: fields.mode, allowed_actions: actions, connection_ids: String(fields.connections).split(",").map(s => s.trim()).filter(Boolean), resource_filters: recipient ? { [actions[0]]: { allowed_recipients: [recipient] } } : {}, requires_approval_for: actions, per_action_limit_minor: fields.limit ? Math.round(Number(fields.limit) * 100) : null, currency: "USD", expires_at: expiry ? new Date(expiry).toISOString() : null } }); await load(); setNotice("Policy proposed. Review and sign it before activation."); } catch (e) { setFailure((e as Error).message); } }}><label>Execution mode<select name="mode"><option value="supervised">Supervised · approval for every action</option><option value="live">Live · within the signed policy</option></select></label><label>Allowed action names<input name="actions" placeholder="erp.order.create" required /></label><label>Connection IDs<input name="connections" placeholder="Comma-separated connection IDs" /></label><label>Only this email recipient (optional)<input name="recipient" type="email" /></label><label>Policy expiration (optional)<input name="expires" type="datetime-local" /></label><label>Per-action amount ceiling (USD)<input name="limit" type="number" min="0" step="0.01" /></label><p className="small-print">This form requires human approval for every listed action. Review exact resource restrictions before signing.</p><button className="button secondary wide" disabled={!can("policies:write")}>Propose policy</button></form><div className="form-divider">after trial and policy approval</div><button className="button primary wide" disabled={!can("automations:activate")} onClick={async () => { try { await api(`/v1/automations/${automation.id}/activate`, { method: "POST", body: { mode: "supervised", expected_version: automation.version } }); await onChange(); setNotice("Supervised activation recorded."); } catch (e) { setFailure((e as Error).message); } }}>Activate supervised mode</button></div></Panel></div>;
}

function Approvals({ can }: { can: (p: string) => boolean }) {
  const [status, setStatus] = useState("pending"); const { data, error, loading, load } = useResource<{ approvals: Approval[] }>(`/v1/approvals?status=${status}`); const [failure, setFailure] = useState<string | null>(null); const [selected, setSelected] = useState<string | null>(null);
  return <><PageTitle eyebrow="HUMAN JUDGMENT, WHERE IT MATTERS" title="You have the final say." description="Review the proposed action, its cost and evidence before anything moves forward." /><div className="tabs">{["pending", "approved", "denied", "expired"].map(t => <button key={t} className={status === t ? "selected" : ""} onClick={() => setStatus(t)}>{human(t)}</button>)}</div><ErrorBox error={error || failure} retry={load} />{loading ? <Loading /> : data?.approvals.length ? data.approvals.map(a => <Panel key={a.id} className="approval-card"><div className="panel-body"><div className="inline-between"><div className="approval-title"><span className="row-icon amber"><Icon name="shield" /></span><div><h2>{a.title}</h2><p>{a.external_system || "External action"} · {a.risk_tier}</p></div></div><Badge status={a.status}>{human(a.status)}</Badge></div><p>{a.summary}</p><div className="approval-meta"><span>Expires {date(a.expires_at)}</span><span>{a.required_approvals} approval{a.required_approvals > 1 ? "s" : ""} required</span><span>Estimated execution cost: {a.estimated_cost_usd ? money(a.estimated_cost_usd) : "not provided"}</span></div><button className="text-button" onClick={() => setSelected(selected === a.id ? null : a.id)}>{selected === a.id ? "Hide" : "Inspect"} proposed record and source evidence<Icon name="down" size={15} /></button>{selected === a.id && <div className="evidence-grid"><div><h3>Before</h3><JsonView value={a.records_before} /></div><div><h3>Proposed result</h3><JsonView value={a.records_after_preview} /></div><div className="span-two"><h3>Source evidence</h3><JsonView value={a.source_evidence} /></div></div>}{a.status === "pending" && <form className="approval-form" onSubmit={async e => { e.preventDefault(); const form = new FormData(e.currentTarget); const submitter = (e.nativeEvent as SubmitEvent).submitter as HTMLButtonElement | null; const decision = submitter?.value || "deny"; try { await api(`/v1/approvals/${a.id}/decide`, { method: "POST", body: { decision, reason: form.get("reason") || null, expected_version: a.version } }); await load(); } catch (err) { setFailure((err as Error).message); } }}><label className="grow">Decision note<input name="reason" placeholder="Optional reason for the audit history" maxLength={2000} /></label><div className="button-row"><button name="decision" value="deny" className="button secondary" disabled={!can("approvals:decide")}>Deny</button><button name="decision" value="approve" className="button primary" disabled={!can("approvals:decide")}><Icon name="check" size={16} />Approve exact action</button></div></form>}</div></Panel>) : <Panel><Empty icon="shield" title={status === "pending" ? "Nothing waiting on you." : `No ${status} approvals`}>{status === "pending" ? "When a workflow needs your judgment, the proposed record and supporting evidence will appear here." : "Decisions remain in your audit history."}</Empty></Panel>}</>;
}

function Activity() {
  const { data, error, loading, load } = useResource<{ events: AuditEvent[] }>("/v1/audit/events?limit=200"); const [result, setResult] = useState("");
  return <><PageTitle title="A record you can follow." description="An append-only history of actions, decisions and permission changes." action={<button className="button secondary" onClick={async () => { try { const r = await api<Row>("/v1/audit/verify"); setResult(`Audit verification: ${json(r)}`); } catch (e) { setResult((e as Error).message); } }}><Icon name="shield" size={17} />Verify audit chain</button>} /><ErrorBox error={error} retry={load} />{result && <div className="notice-box" role="status">{result}</div>}<Panel>{loading ? <Loading /> : data?.events.length ? <div className="table-wrap"><table><thead><tr><th>Event</th><th>Actor</th><th>Category</th><th>Time</th><th>Sequence</th></tr></thead><tbody>{data.events.map(e => <tr key={e.seq}><td><strong>{human(e.event_type)}</strong><small className="table-subtitle">{e.resource_id}</small></td><td>{e.actor_kind}<small className="table-subtitle">{e.actor_id}</small></td><td><Badge>{e.category}</Badge></td><td>{date(e.created_at)}</td><td className="mono">#{e.seq}</td></tr>)}</tbody></table></div> : <Empty icon="clock" title="No recorded events yet">Activity will appear as you configure your business.</Empty>}</Panel></>;
}

function Connections({ path, can }: { path: string; can: (p: string) => boolean }) {
  const { data, error, loading, load } = useResource<{ connections: Row[] }>("/v1/connections"); const [failure, setFailure] = useState<string | null>(null); const [session, setSession] = useState<Row | null>(null); const [busy, setBusy] = useState(false); const [gmailSend, setGmailSend] = useState(false);
  useEffect(() => { if (path.startsWith("/setup/")) api<Row>(`/v1/connections/sessions/${path.split("/")[2]}`).then(setSession).catch(e => setFailure(e.message)); }, [path]);
  async function begin(provider: string) { setBusy(true); setFailure(null); try { setSession(await api<Row>("/v1/connections/sessions", { method: "POST", body: { provider, capabilities: provider === "gmail" ? ["read_order_messages", ...(gmailSend ? ["send_order_confirmations"] : [])] : [] } })); } catch (e) { setFailure((e as Error).message); } finally { setBusy(false); } }
  return <><PageTitle title="Your tools. One workspace." description="Securely authorize provider accounts. Each automation still needs its own permission to act." /><ConnectionNotice /><ErrorBox error={failure} />{session && <Panel title="Connection setup"><div className="panel-body"><Badge status={String(session.status)}>{human(session.status)}</Badge><h3>{human(session.provider)}</h3><p>{String(session.next_step || session.message || "Review requested access, then continue to the provider’s secure authorization page.")}</p><p className="small-print">Expires {date(session.expires_at)}. A setup link alone never authorizes access.</p><JsonView value={session.requested_scopes || session.requirements || session.configuration_required || session.capabilities || []} />{["whatsapp_business", "shopify", "elevenlabs"].includes(String(session.provider)) && <ProviderConnect provider={String(session.provider)} can={can} />}<div className="button-row"><button className="button primary" disabled={!can("connections:manage") || session.status !== "requires_external_authorization"} onClick={async () => { try { const r = await api<Row>(`/v1/connections/sessions/${session.session_id || session.id}/authorize`, { method: "POST" }); const url = new URL(String(r.authorization_url)); if (url.protocol !== "https:") throw new Error("Provider authorization requires HTTPS."); window.location.assign(url.toString()); } catch (e) { setFailure((e as Error).message); } }}>Continue to provider<Icon name="arrow" size={16} /></button><button className="button secondary" onClick={async () => { try { setSession(await api<Row>(`/v1/connections/sessions/${session.session_id || session.id}`)); await load(); } catch (e) { setFailure((e as Error).message); } }}>Refresh status</button><button className="button danger-outline" onClick={async () => { try { setSession(await api<Row>(`/v1/connections/sessions/${session.session_id || session.id}/cancel`, { method: "POST" })); await load(); } catch (e) { setFailure((e as Error).message); } }}>Cancel setup</button><button className="text-button" onClick={() => setSession(null)}>Close</button></div></div></Panel>}
    <Panel title="Connected accounts"><ErrorBox error={error} retry={load} />{loading ? <Loading /> : data?.connections.length ? <div className="panel-body">{data.connections.map(c => <div className="connection-row" key={String(c.id)}><span className="row-icon"><Icon name="link" /></span><div className="grow"><strong>{String(c.account_display || c.provider)}</strong><small>{human(c.provider)} · {human(c.environment)} · ID {String(c.id)}</small><small>{Array.isArray(c.scopes) ? c.scopes.join(" · ") : "Scopes not reported"}</small></div><Badge status={String(c.status)}>{human(c.status)}</Badge><div className="button-row"><button className="button secondary compact" disabled={!can("connections:manage")} onClick={async () => { try { await api(`/v1/connections/${c.id}/verify`, { method: "POST" }); await load(); } catch (e) { setFailure((e as Error).message); } }}>Verify</button>{!c.account_confirmed && <button className="button primary compact" disabled={!can("connections:manage")} onClick={async () => { try { await api(`/v1/connections/${c.id}/confirm`, { method: "POST" }); await load(); } catch (e) { setFailure((e as Error).message); } }}>Confirm account</button>}<button className="button danger-outline compact" disabled={!can("connections:manage")} onClick={async () => { try { await api(`/v1/connections/${c.id}`, { method: "DELETE" }); await load(); } catch (e) { setFailure((e as Error).message); } }}>Disconnect</button></div></div>)}</div> : <Empty icon="link" title="A clean slate for your connections">Connect only the accounts your workflows need. Credentials stay encrypted on the server.</Empty>}</Panel><label className="checkbox-label"><input type="checkbox" checked={gmailSend} onChange={e => setGmailSend(e.target.checked)} /><span>Request Gmail confirmation sending as well as reading. Sending still requires a separate signed automation policy.</span></label><div className="provider-grid">{[{ id: "gmail", title: "Gmail", icon: "mail", text: "Read authorized orders and send approved messages through Google OAuth." }, { id: "whatsapp_business", title: "WhatsApp Business", icon: "link", text: "Sign in through Meta's own window and pick your business number. Personal WhatsApp is not supported." }, { id: "elevenlabs", title: "Telephone & ElevenLabs", icon: "pulse", text: "Requires an authorized inbound number or verified carrier forwarding and a real test call." }, { id: "shopify", title: "Shopify", icon: "box", text: "Install Gluons from Shopify, then choose this business. Identity and payment verification stay with the owner." }].map(p => <Panel key={p.id}><div className="panel-body"><span className="skill-icon tone-0"><Icon name={p.icon} size={24} /></span><h2>{p.title}</h2><p className="body-copy">{p.text}</p>{p.id === "gmail" ? <button className="button secondary" disabled={busy || !can("connections:manage")} onClick={() => begin(p.id)}>Review setup requirements<Icon name="arrow" size={16} /></button> : <ProviderConnect provider={p.id} can={can} />}</div></Panel>)}</div></>;
}

function Knowledge({ can }: { can: (p: string) => boolean }) {
  const { data, error, loading, load } = useResource<{ documents: Row[] }>("/v1/knowledge/documents"); const [failure, setFailure] = useState<string | null>(null);
  return <><PageTitle title="The context behind good work." description="Keep approved business knowledge in one tenant-scoped place. Documents provide context; they never change permissions." /><div className="detail-grid"><Panel title="Business knowledge"><ErrorBox error={error} retry={load} />{loading ? <Loading /> : data?.documents.length ? <div className="panel-body">{data.documents.map(d => <details className="knowledge-item" key={String(d.id)}><summary><Icon name="box" size={18} /><strong>{String(d.title)}</strong><Badge>{human(d.kind)}</Badge></summary><p>{String(d.body || d.excerpt || "")}</p><small>{date(d.created_at)}{d.source ? ` · ${d.source}` : ""}</small></details>)}</div> : <Empty icon="box" title="A shared source of context">Add your operating hours, product notes and approved business procedures.</Empty>}</Panel><Panel title="Add a note"><div className="panel-body"><ErrorBox error={failure} /><form onSubmit={async e => { e.preventDefault(); const form = e.currentTarget; const fields = Object.fromEntries(new FormData(form)); try { await api("/v1/knowledge/documents", { method: "POST", body: { ...fields, kind: "note", source: fields.source || null } }); form.reset(); await load(); } catch (err) { setFailure((err as Error).message); } }}><label>Title<input name="title" required maxLength={200} placeholder="Business hours and service area" /></label><label>Approved content<textarea name="body" rows={8} required placeholder="Add factual information your automations may use…" /></label><label>Source reference<input name="source" placeholder="Optional source URL or document reference" /></label><button className="button primary wide" disabled={!can("knowledge:write")}>Save knowledge<Icon name="plus" size={16} /></button></form></div></Panel></div></>;
}

function Costs({ org, can, onUpdate }: { org: Organization | null; can: (p: string) => boolean; onUpdate: () => Promise<void> }) {
  const { data, error, load } = useResource<Spending>("/v1/billing/usage"); const report = useResource<Row>("/v1/reports/roi"); const [failure, setFailure] = useState<string | null>(null); const [saved, setSaved] = useState(false);
  return <><PageTitle title="Clarity on every dollar." description="Recorded usage and explicit ceilings. Measured costs and estimated benefits remain separate." /><ErrorBox error={error || failure} retry={load} /><div className="stat-grid three"><Stat label="Recorded usage this month" value={data ? money(data.total_usd) : "—"} icon="money" note={data ? `From ${date(data.period_start)}` : "Loading recorded usage"} /><Stat label="Business monthly ceiling" value={org?.monthly_budget_usd ? money(org.monthly_budget_usd) : "Not set"} icon="shield" note="Checked server-side before spend" /><Stat label="Savings evidence" value="Evidence first" icon="chart" note="No savings assumed from completed tasks" /></div><div className="detail-grid"><Panel title="Usage ledger by provider">{data?.breakdown.length ? <div className="table-wrap"><table><thead><tr><th>Provider</th><th>Category</th><th>Basis</th><th>Events</th><th>Cost</th></tr></thead><tbody>{data.breakdown.map((r, i) => <tr key={i}><td>{r.provider}</td><td>{human(r.category)}</td><td><Badge>{r.cost_basis}</Badge></td><td>{r.events}</td><td>{money(r.cost_usd)}</td></tr>)}</tbody></table></div> : <Empty icon="money" title="No usage recorded yet">Usage is added when a task incurs a tracked cost. External vendor charges may need reconciliation.</Empty>}</Panel><Panel title="Keep spend in bounds"><div className="panel-body">{saved && <div className="success-box" role="status">Monthly budget saved.</div>}<form onSubmit={async e => { e.preventDefault(); setFailure(null); const f = new FormData(e.currentTarget); try { await api("/v1/organizations/current", { method: "PATCH", body: { monthly_budget_usd: f.get("budget") === "" ? null : Number(f.get("budget")) } }); await onUpdate(); await load(); setSaved(true); } catch (err) { setFailure((err as Error).message); } }}><label>Monthly business budget (USD)<input key={org?.monthly_budget_usd} name="budget" type="number" min="0" step="0.01" defaultValue={org?.monthly_budget_usd || ""} placeholder="Set a monthly ceiling" /></label><p className="body-copy">New chargeable work stops when recorded spend and reserved costs reach this ceiling.</p><button className="button primary" disabled={!can("billing:manage")}>Save monthly budget</button></form></div></Panel></div><Panel title="Proof & ROI"><div className="panel-body"><ErrorBox error={report.error} />{report.data ? <JsonView value={report.data} /> : <p className="body-copy">ROI needs baseline evidence, recorded time studies and verified costs. Your workspace will show those assumptions alongside any estimates.</p>}</div></Panel></>;
}

function Security({ session, org, can, onUpdate }: { session: Session; org: Organization | null; can: (p: string) => boolean; onUpdate: () => Promise<void> }) {
  const members = useResource<{ members: Row[] }>("/v1/organizations/current/members"); const sessions = useResource<{ sessions: Row[]; current: string }>("/v1/auth/sessions"); const assistants = useResource<{ assistants: Row[] }>("/v1/assistants"); const [error, setError] = useState<string | null>(null); const [notice, setNotice] = useState(""); const [mfa, setMfa] = useState<Row | null>(null);
  return <><PageTitle title="Trust starts with control." description={`Manage who can act for ${org?.name}, review active sessions and stop external actions.`} /><ErrorBox error={error} />{notice && <div className="success-box" role="status">{notice}</div>}<Panel title="Your team"><ErrorBox error={members.error} retry={members.load} /><div className="panel-body">{members.data?.members.map(m => <div className="member-row" key={String(m.id)}><span className="user-avatar">{String(m.display_name || m.email || "?")[0]}</span><div className="grow"><strong>{String(m.display_name || m.email)}</strong><small>{String(m.email)}</small></div><Badge>{human(m.role)}</Badge>{can("members:manage") && <><select aria-label={`Role for ${m.email}`} className="member-role" value={String(m.role)} onChange={async e => { try { await api(`/v1/organizations/current/members/${m.id}`, { method: "PATCH", body: { role: e.target.value } }); await members.load(); } catch (err) { setError((err as Error).message); } }}>{["owner", "admin", "operator", "approver", "viewer", "field_rep", "support"].map(role => <option key={role}>{role}</option>)}</select><button className="button danger-outline compact" onClick={async () => { try { await api(`/v1/organizations/current/members/${m.id}`, { method: "DELETE" }); await members.load(); } catch (err) { setError((err as Error).message); } }}>Remove member</button></>}</div>)}{can("members:manage") && <form className="inline-form" onSubmit={async e => { e.preventDefault(); const form = e.currentTarget; const f = Object.fromEntries(new FormData(form)); try { await api("/v1/organizations/current/invitations", { method: "POST", body: f }); setNotice("Invitation sent through the configured account email delivery."); form.reset(); } catch (err) { setError((err as Error).message); } }}><label className="grow">Invite by email<input type="email" name="email" required placeholder="teammate@business.com" /></label><label>Role<select name="role">{[...(org?.role === "owner" ? ["owner"] : []), "viewer", "operator", "approver", "admin", "field_rep", "support"].map(r => <option key={r}>{r}</option>)}</select></label><button className="button secondary">Send invitation<Icon name="arrow" size={16} /></button></form>}</div></Panel><div className="home-bottom"><Panel title="Connected assistants"><ErrorBox error={assistants.error} retry={assistants.load} /><div className="panel-body">{assistants.data?.assistants.length ? assistants.data.assistants.map(a => <div className="member-row" key={String(a.id)}><span className="row-icon"><Icon name="spark" /></span><div className="grow"><strong>{String(a.client_name || a.provider || a.client_id)}</strong><small>{human(a.status)} · {Array.isArray(a.scopes) ? a.scopes.join(", ") : ""}</small></div><button className="button danger-outline compact" disabled={!can("assistants:manage")} onClick={async () => { try { await api(`/v1/assistants/${a.id}/revoke`, { method: "POST" }); await assistants.load(); } catch (err) { setError((err as Error).message); } }}>Revoke</button></div>) : <Empty icon="spark" title="Your assistants connect here">Use a compatible remote MCP client to authorize Gluons. Each authorization can be revoked independently.</Empty>}</div></Panel><Panel title="Account security"><div className="panel-body"><p className="body-copy">Signed in as <strong>{session.user.email}</strong>. Add an authenticator for a second layer of protection.</p><button className="button secondary" onClick={async () => { try { setMfa(await api<Row>("/v1/auth/mfa/enroll", { method: "POST" })); } catch (err) { setError((err as Error).message); } }}>Set up authenticator</button>{mfa && <div className="mfa-setup"><p>Store this authenticator setup in your password manager. Keep it private.</p><JsonView value={mfa} /><form onSubmit={async e => { e.preventDefault(); try { const result = await api<Row>("/v1/auth/mfa/confirm", { method: "POST", body: Object.fromEntries(new FormData(e.currentTarget)) }); setMfa(result); setNotice("Authenticator enabled. Save the recovery codes securely."); } catch (err) { setError((err as Error).message); } }}><label>Authenticator code<input name="code" required autoComplete="one-time-code" /></label><button className="button primary">Confirm authenticator</button></form></div>}</div></Panel></div><Panel title="Sign-in sessions"><ErrorBox error={sessions.error} retry={sessions.load} /><div className="panel-body">{sessions.data?.sessions.map(s => <div className="member-row" key={String(s.id)}><span className="row-icon"><Icon name="shield" /></span><div className="grow"><strong>{s.id === sessions.data?.current ? "This session" : "Signed-in session"}</strong><small>{String(s.user_agent || "Unknown browser")} · {date(s.created_at)}</small></div><button className="button secondary compact" onClick={async () => { try { await api(`/v1/auth/sessions/${s.id}`, { method: "DELETE" }); if (s.id === sessions.data?.current) await onUpdate(); else await sessions.load(); } catch (err) { setError((err as Error).message); } }}>Revoke session</button></div>)}</div></Panel>{can("emergency:stop") && <Panel title="Emergency control"><div className="panel-body inline-between"><div><h3>Stop new external actions</h3><p className="body-copy">Immediately fence new side effects for this business. Already committed actions remain in the audit history.</p></div><button className="button danger-outline" onClick={async () => { try { await api("/v1/organizations/current/emergency-stop", { method: "POST", body: { active: !org?.emergency_stop_at } }); await onUpdate(); } catch (err) { setError((err as Error).message); } }}><Icon name="stop" size={17} />{org?.emergency_stop_at ? "Release emergency stop" : "Stop external actions"}</button></div></Panel>}</>;
}

function AssistantConsent() {
  const [consent, setConsent] = useState<Row | null>(null); const [error, setError] = useState<string | null>(null); const [requestId, setRequestId] = useState(""); const [busy, setBusy] = useState(false);
  useEffect(() => { const id = new URLSearchParams(window.location.search).get("request_id") || ""; setRequestId(id); if (id) api<Row>(`/v1/assistants/consent/${encodeURIComponent(id)}`).then(setConsent).catch(e => setError(e.message)); else setError("This authorization request is missing its request ID."); }, []);
  async function decide(approve: boolean) { setBusy(true); try { const r = await api<{ redirect_url: string }>(`/v1/assistants/consent/${encodeURIComponent(requestId)}`, { method: "POST", body: { approve } }); const target = new URL(r.redirect_url); if (!["https:", "http:"].includes(target.protocol)) throw new Error("Unsupported assistant callback URL."); window.location.assign(target.toString()); } catch (e) { setError((e as Error).message); setBusy(false); } }
  return <><PageTitle eyebrow="ASSISTANT AUTHORIZATION" title="Connect an assistant, on your terms." description="This authorizes access to Gluons. It does not connect provider accounts or sign automation policies." /><ErrorBox error={error} />{consent && <Panel title={String(consent.client_name || "Assistant access request")}><div className="panel-body narrow"><dl className="facts"><div><dt>Business</dt><dd>{String(consent.organization_name)}</dd></div><div><dt>Client</dt><dd>{String(consent.client_id)} (name not verified)</dd></div><div><dt>Requested scopes</dt><dd>{Array.isArray(consent.scopes) ? consent.scopes.join(", ") : String(consent.scopes)}</dd></div><div><dt>Expires</dt><dd>{date(consent.expires_at)}</dd></div><div><dt>Callback</dt><dd className="mono">{String(consent.redirect_uri)}</dd></div></dl><div className="notice-box"><Icon name="shield" size={18} />{String(consent.notice || "The assistant receives only the granted permissions for the selected business. Financial and legal authority remains on Gluons Web.")}</div><div className="button-row"><button className="button secondary" disabled={busy} onClick={() => decide(false)}>Deny access</button><button className="button primary" disabled={busy} onClick={() => decide(true)}>Authorize assistant<Icon name="arrow" size={17} /></button></div></div></Panel>}</>;
}
function AcceptInvite({ onDone }: { onDone: () => Promise<void> }) {
  const [error, setError] = useState<string | null>(null); const [notice, setNotice] = useState("");
  return <Panel title="Join a business"><div className="panel-body"><p>Accept the invitation sent to your verified email address.</p><ErrorBox error={error} />{notice && <div className="success-box">{notice}</div>}<button className="button primary" onClick={async () => { const p = new URLSearchParams(window.location.search); try { await api(`/v1/organizations/${encodeURIComponent(p.get("org") || "")}/invitations/accept`, { method: "POST", body: { token: p.get("token") } }); setNotice("Invitation accepted. Choose this business from your workspace selector."); await onDone(); } catch (e) { setError((e as Error).message); } }}>Accept invitation</button></div></Panel>;
}

function TrialStudio({ automation, can, onChange }: { automation: Automation; can: (p: string) => boolean; onChange: () => Promise<void> }) {
  const trials = useResource<{ trials: Row[] }>("/v1/trials");
  const [report, setReport] = useState<Row | null>(null); const [error, setError] = useState<string | null>(null);
  const rows = trials.data?.trials.filter(t => t.automation_id === automation.id) || [];
  const measured = report?.measured as Row | undefined;
  return <><div className="detail-grid"><Panel title="Trial Studio"><div className="panel-body"><p className="body-copy">Test against explicit expected outcomes. A completed trial is not a passing trial unless the comparison set meets the server’s quality requirements.</p><ErrorBox error={error || trials.error} />{rows.length ? rows.map(t => <div className="member-row" key={String(t.id)}><span className="row-icon"><Icon name="spark" /></span><div className="grow"><strong>{human(t.mode)}</strong><small>{date(t.created_at)} · {human(t.status)}</small></div><button className="button secondary compact" onClick={async () => { try { setReport(await api<Row>(`/v1/trials/${t.id}/results`)); } catch (e) { setError((e as Error).message); } }}>Inspect report</button>{t.status !== "completed" && can("trials:write") && <button className="button secondary compact" onClick={async () => { try { setReport(await api<Row>(`/v1/trials/${t.id}/complete`, { method: "POST" })); await trials.load(); await onChange(); } catch (e) { setError((e as Error).message); } }}>Complete trial</button>}</div>) : <Empty icon="spark" title="Start with evidence">Replay and shadow trials produce no external writes.</Empty>}</div></Panel><Panel title="Define a comparison"><div className="panel-body"><form onSubmit={async e => { e.preventDefault(); setError(null); const f = new FormData(e.currentTarget); try { await api(`/v1/automations/${automation.id}/start-trial`, { method: "POST", body: { expected_version: automation.version, mode: f.get("mode"), comparator: { expected_outcomes: JSON.parse(String(f.get("outcomes"))), minimum_cases: Number(f.get("minimum")) }, baseline: { method: f.get("baseline") }, budget_usd: f.get("budget") ? Number(f.get("budget")) : null } }); await trials.load(); await onChange(); } catch (err) { setError(err instanceof SyntaxError ? "Expected outcomes must be a valid JSON object indexed by source event ID." : (err as Error).message); } }}><label>Trial mode<select name="mode"><option value="shadow">Shadow · process inputs without external writes</option><option value="historical_replay">Historical replay · evaluate past inputs</option></select></label><label>Minimum labelled cases<input name="minimum" type="number" min="1" max="10000" defaultValue="10" required /></label><label>Expected outcomes by source event ID<textarea name="outcomes" rows={6} defaultValue="{}" spellCheck={false} required /></label><label>Baseline method<input name="baseline" placeholder="How did you measure the existing workflow?" /></label><label>Trial budget (USD)<input name="budget" type="number" min="0" step="0.01" /></label><button className="button primary wide" disabled={!can("trials:write")}>Start defined trial<Icon name="play" size={16} /></button></form></div></Panel></div>{report && <Panel title="Trial evidence"><div className="panel-body"><div className="inline-between"><Badge status={report.passed ? "verified" : "pending"}>{report.passed ? "Comparison passed" : "More evidence needed"}</Badge><span className="subtle">{human(report.mode)} · {human(report.status)}</span></div><div className="stat-grid three" style={{ marginTop: 20 }}><Stat label="Measured runs" value={String(measured?.runs ?? "—")} icon="layers" note={`${measured?.completed || 0} completed`} /><Stat label="Labelled comparisons" value={String(measured?.labelled_cases ?? "—")} icon="check" note={`${measured?.correct_cases || 0} correct`} /><Stat label="External writes" value={String(measured?.external_writes ?? "—")} icon="shield" note="Must be zero in shadow and replay" /></div><p className="body-copy">{String(report.quality_basis)}</p>{Array.isArray(report.missing_evidence) && report.missing_evidence.map((item, i) => <div className="notice-box" key={i}>{String(item)}</div>)}<details><summary>View full recorded report</summary><JsonView value={report} /></details></div></Panel>}<TrialEvidence automationId={automation.id} version={automation.version} status={String(automation.status)} mode={String(automation.mode)} trials={rows} can={can} onChange={async () => { await trials.load(); await onChange(); }} /></>;
}

function RunDetail({ id }: { id: string }) {
  const { data, error, loading, load } = useResource<Row>(`/v1/runs/${id}`); const [diagnosis, setDiagnosis] = useState<Row | null>(null); const [failure, setFailure] = useState<string | null>(null);
  if (loading) return <Loading />; if (!data) return <ErrorBox error={error} retry={load} />;
  const events = Array.isArray(data.events) ? data.events as Row[] : []; const receipts = Array.isArray(data.receipts) ? data.receipts as Row[] : [];
  return <><Link className="back-link" href={`/automations/${data.automation_id}`}>← Back to automation</Link><PageTitle title="Every step, accounted for." description={`${id} · ${human(data.source)} · ${human(data.mode)}`} action={<Badge status={String(data.status)}>{human(data.status)}</Badge>} /><ErrorBox error={failure} /><div className="detail-grid"><Panel title="Execution timeline"><div className="panel-body">{events.length ? events.map(e => <div className="activity-item" key={String(e.seq)}><span className="activity-symbol"><Icon name="clock" size={16} /></span><div><strong>{human(e.type)}</strong><small>{date(e.at)}</small><details><summary>Inspect event</summary><JsonView value={e.data} /></details></div></div>) : <Empty icon="clock" title="No events recorded">Refresh after the worker processes this run.</Empty>}</div></Panel><Panel title="Outcome and diagnosis"><div className="panel-body"><dl className="facts"><div><dt>Recorded cost</dt><dd>{money(data.cost_usd)}</dd></div><div><dt>Started</dt><dd>{date(data.started_at)}</dd></div><div><dt>Finished</dt><dd>{date(data.finished_at)}</dd></div></dl><JsonView value={data.outcome} /><button className="button secondary" onClick={async () => { try { setDiagnosis(await api<Row>(`/v1/runs/${id}/diagnosis`)); } catch (e) { setFailure((e as Error).message); } }}>Inspect failure diagnosis</button>{diagnosis && <JsonView value={diagnosis} />}</div></Panel></div><Panel title="Verified receipts"><div className="panel-body">{receipts.length ? receipts.map(r => <div className="receipt" key={String(r.id)}><div className="inline-between"><strong>{human(r.action)}</strong><Badge status={r.verified ? "verified" : "pending"}>{r.verified ? "Verified by readback" : human(r.status)}</Badge></div><p>{human(r.environment)} · {String(r.provider)}</p><JsonView value={r} /></div>) : <Empty icon="shield" title="No external receipts">Shadow results are previews; a model response is never external transaction proof.</Empty>}</div></Panel></>;
}







